package com.bank.dup.service;

import com.bank.dup.model.Employee;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class DuplicateFinderService {
    private static final Logger log = Logger.getLogger(DuplicateFinderService.class.getName());

    public List<String> duplicateNames(List<Employee> employees) {
        // Pass 1: build name -> count.
        Map<String, Long> counts = employees.stream()
                .collect(Collectors.groupingBy(Employee::getName, Collectors.counting()));
        log.info(() -> "Name counts: " + counts);

        // Pass 2: keep names seen more than once.
        return counts.entrySet().stream()
                .filter(entry -> entry.getValue() > 1)
                .map(Map.Entry::getKey)
                .collect(Collectors.toList());
    }
}
