package com.bank.dup;

import com.bank.dup.model.Employee;
import com.bank.dup.service.DuplicateFinderService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("E1", "Rajesh"),
            new Employee("E2", "Priya"),
            new Employee("E3", "Rajesh"),  // duplicate name
            new Employee("E4", "Amit"),
            new Employee("E5", "Priya")    // duplicate name
        );

        List<String> dups = new DuplicateFinderService().duplicateNames(staff);
        dups.forEach(n -> log.warning(() -> "Duplicate name found: " + n));
    }
}
